// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.memory.repositoryimport com.roshan.persona.common.Resultimport com.roshan.persona.database.dao.SemanticFactDaoimport com.roshan.persona.database.entity.SemanticFactEntityimport timber.log.Timberimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.AppError/** * NOUS — Semantic Fact Repository. * * Stores and retrieves semantic facts (general knowledge). * Uses Bayesian confidence (alpha/beta) and temporal versioning. */class SemanticFactRepository(    private val dao: SemanticFactDao,) {    suspend fun store(        subjectEntityId: Long?,        predicate: String,        objectValue: String,        objectEntityId: Long?,        source: String,    ): Result<Long> {        return try {            val now = System.currentTimeMillis()            val entity = SemanticFactEntity(                subjectEntityId = subjectEntityId,                predicate = predicate,                objectValue = objectValue,                objectEntityId = objectEntityId,                confidenceAlpha = 1.0f,                confidenceBeta = 0.0f,                source = source,                validFrom = now,                validTo = null,                supersededBy = null,                isDeleted = false,                createdAt = now,                updatedAt = now,            )            val id = dao.insert(entity)            Result.Success(id, CorrelationId.generate(), 0)        } catch (e: Exception) {            Timber.e(e, "Failed to store semantic fact")            Result.Failure(AppError.from(e), CorrelationId.generate(), 0)        }    }    suspend fun getForSubject(entityId: Long): Result<List<SemanticFactEntity>> {        return try { Result.Success(dao.getForSubject(entityId), CorrelationId.generate(), 0) } catch (e: Exception) { Result.Failure(AppError.from(e), CorrelationId.generate(), 0) }    }    suspend fun getByPredicate(predicate: String): Result<List<SemanticFactEntity>> {        return try { Result.Success(dao.getByPredicate(predicate), CorrelationId.generate(), 0) } catch (e: Exception) { Result.Failure(AppError.from(e), CorrelationId.generate(), 0) }    }    suspend fun reinforce(id: Long): Result<Unit> {        return try { dao.reinforce(id); Result.Success(Unit, CorrelationId.generate(), 0) } catch (e: Exception) { Result.Failure(AppError.from(e), CorrelationId.generate(), 0) }    }    suspend fun contradict(id: Long): Result<Unit> {        return try { dao.contradict(id); Result.Success(Unit, CorrelationId.generate(), 0) } catch (e: Exception) { Result.Failure(AppError.from(e), CorrelationId.generate(), 0) }    }    suspend fun supersede(oldId: Long, newId: Long): Result<Unit> {        return try { dao.supersede(oldId, newId, System.currentTimeMillis()); Result.Success(Unit, CorrelationId.generate(), 0) } catch (e: Exception) { Result.Failure(AppError.from(e), CorrelationId.generate(), 0) }    }    suspend fun forget(id: Long): Result<Unit> {        return try { dao.softDelete(id); Result.Success(Unit, CorrelationId.generate(), 0) } catch (e: Exception) { Result.Failure(AppError.from(e), CorrelationId.generate(), 0) }    }    suspend fun count(): Int = try { dao.count() } catch (e: Exception) { 0 }}
